import json
import math
import statistics

dates = ["2025-03-03", "2025-03-04", "2025-03-05", "2025-03-06", "2025-03-07", "2025-03-10"]
closes = {
    "AAA": [80.0, 82.4, 83.1, 79.5, 77.25, 81.0],
    "BBB": [212.5, 213.0, 215.75, 216.2, 219.8, 221.4],
}
tickers = ["AAA", "BBB"]
prices = {"dates": dates, "tickers": tickers, "closes": closes}
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}
w = 2
vol = {}
for t, r in rets.items():
    vol[t] = [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
vols = {"returns": returns, "window": w, "annualized": True, "values": vol}


def summ(t):
    r = rets[t]
    ar = 252 * statistics.fmean(r)
    av = math.sqrt(252) * statistics.stdev(r)
    return {"ticker": t, "ann_return": ar, "ann_vol": av, "sharpe": ar / av if av else 0.0, "last_vol": vol[t][-1]}


def dd(t):
    wealth = 1.0
    peak, peak_d = 1.0, dates[0]
    best = (0.0, dates[0], dates[0])
    for d, r in zip(dates[1:], rets[t]):
        wealth *= math.exp(r)
        if wealth > peak:
            peak, peak_d = wealth, d
        depth = wealth / peak - 1
        if depth < best[0]:
            best = (depth, peak_d, d)
    return {"ticker": t, "depth": best[0], "peak_date": best[1], "trough_date": best[2]}


s = {t: summ(t) for t in tickers}
d = {t: dd(t) for t in tickers}
rows = [
    {**s[t], "max_drawdown": d[t]["depth"], "peak_date": d[t]["peak_date"], "trough_date": d[t]["trough_date"]}
    for t in tickers
]
for r in rows:
    r.pop("ticker")
rows = [{"ticker": t, **r} for t, r in zip(tickers, rows)]
out = {
    "mdata.Prices": prices,
    "risk.Returns": returns,
    "risk.VolSeries": vols,
    "risk.TickerSummary": s["AAA"],
    "risk.Drawdown": {"drawdowns": [d["AAA"], d["BBB"]]},
    "risk.Report": {"path": "report.json", "rows": rows},
}
base = "/Users/connorott/plugins/dev-team-workspace/iteration-b1/minilab-A1-r1/with_skill/project/.claude/worktrees/agent-a894ed74e8a5b7bda/tests/contracts/"
import os

for name, payload in out.items():
    os.makedirs(base + name, exist_ok=True)
    with open(base + name + "/sample.json", "w") as f:
        json.dump(payload, f, indent=1)
        f.write("\n")
    print(name, json.dumps(payload)[:300])
